def check_candidate(val):
    val = abs(val) % n
    if val <= 1: return False
    try:
        sk = SigningKey.from_secret_exponent(val, curve=SECP256k1)
        vk = sk.get_verifying_key()
        pubkey_derived = "04" + binascii.hexlify(vk.to_string()).decode()
        
        if pubkey_derived == target_pubkey_hex:
            print(f"\n[!!!] SUCCESS: Private Key Found [!!!]")
            print(f"Hex: {hex(val)}")
            return True
    except:
        pass
    return False

